import {
  ArrowLeft,
  BookOpen,
  CloudUpload,
  Laptop,
  LogOut,
  Palette,
  ShieldCheck,
  UserRound,
} from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useInkflowAccount } from "../../lib/auth";
import { loadDrawerNotes } from "../../lib/drawerNotes";
import { useKnowledge } from "../../store/knowledge";
import { useThemeStore } from "../../store/theme";
import { useVocabulary } from "../../store/vocabulary";
import { THEME_PRESETS } from "../../theme/palettes";
import { AuthDialog } from "./AuthDialog";
import "./account-page.css";

/**
 * 用户界面（账号这一页）：注册登录之后，自己是谁、数据挂在哪儿，
 * 都该有一处地方能看全 —— 不用去翻设置。
 *
 * 到这儿来的路有两条：目录面板最上面那块账号区按「查看用户界面」，
 * 或者直接把地址栏敲成 /account。没登录也进得来，这一页会告诉你
 * 现在这些东西存在哪台设备上、登录之后会跟着谁走。
 */
export function AccountPage() {
  const account = useInkflowAccount();
  const navigate = useNavigate();
  const themeId = useThemeStore((state) => state.themeId);
  const hydrateWords = useVocabulary((state) => state.hydrate);
  const words = useVocabulary((state) => state.words);
  const hydrateCards = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const [authOpen, setAuthOpen] = useState(false);
  /**
   * onClose 得是个稳定值。登录窗口挂上以后有一支 effect（以 open / onClose
   * 等为依赖）会调 account.clearError() —— 而这一页订的是整个账号 store，
   * store 一 set 整页就重画，重画又生出一个新的 onClose，effect 再跑、
   * 再 clearError……来回就成了死循环（React #185，窗口一开就白屏）。
   * useCallback 把身份钉死，环就断在这儿。
   */
  const closeAuth = useCallback(() => setAuthOpen(false), []);
  /** 便条存在本机 localStorage 里，不在 store 里 —— 翻一次就够，不必订着它。 */
  const [noteCount, setNoteCount] = useState(0);

  useEffect(() => {
    void hydrateWords();
    void hydrateCards();
    setNoteCount(loadDrawerNotes().length);
  }, [hydrateWords, hydrateCards]);

  const user = account.user;
  const themeName = THEME_PRESETS[themeId]?.nameZh ?? "月灰紫";

  return (
    <main className="account-page">
      <header className="account-page__bar">
        <Link to="/shelf" className="account-page__back">
          <ArrowLeft size={16} />
          返回书架
        </Link>
        <span className="account-page__kicker">Account · 账号</span>
      </header>

      {user ? (
        <>
          <section className="account-page__identity" aria-label="账号身份">
            <span className="account-page__avatar" aria-hidden="true">
              {(user.displayName.trim()[0] ?? "L").toUpperCase()}
            </span>
            <div className="account-page__who">
              <h1>{user.displayName}</h1>
              <p>{user.emailMasked ?? user.phoneMasked ?? "Leafia Account"}</p>
              <div className="account-page__badges">
                {account.local ? (
                  <span className="account-page__badge">
                    <Laptop size={13} />
                    本机账号 · 跟着这台设备
                  </span>
                ) : (
                  <span className="account-page__badge is-synced">
                    <CloudUpload size={13} />
                    已登录 · 数据跟着账号走
                  </span>
                )}
                {user.wechatBound ? (
                  <span className="account-page__badge">
                    <ShieldCheck size={13} />
                    微信已绑定
                  </span>
                ) : null}
              </div>
            </div>
          </section>

          <section className="account-page__stats" aria-label="我的数据">
            <article>
              <small>Words · 单词本</small>
              <strong>{words.length}</strong>
              <span>收在单词本里的词</span>
            </article>
            <article>
              <small>Knowledge · 知识卡</small>
              <strong>{cards.length}</strong>
              <span>书本收藏与自建的知识卡</span>
            </article>
            <article>
              <small>Notes · 便条</small>
              <strong>{noteCount}</strong>
              <span>抽屉里记下的小纸条</span>
            </article>
            <article>
              <small>Skin · 皮肤</small>
              <strong>{themeName}</strong>
              <span>当前书房的样子</span>
            </article>
          </section>

          <section className="account-page__note" aria-label="数据去向">
            <Palette size={16} />
            <p>
              便条、皮肤、单词本和知识卡都挂在这个账号上
              {account.local ? "（这台设备上的账号，换台机器要重新注册）" : "，换台设备登录同一个账号就还在"}
              。想换皮肤去书架近景的皮肤架，退出登录在这页最下面。
            </p>
          </section>

          <div className="account-page__actions">
            <Link to="/shelf" className="is-primary">
              <BookOpen size={16} />
              回到书架
            </Link>
            <button
              type="button"
              className="is-quiet"
              disabled={account.busy}
              onClick={() => {
                void account.signOut().then(() => navigate("/shelf"));
              }}
            >
              <LogOut size={16} />
              退出登录
            </button>
          </div>
        </>
      ) : (
        <>
          <section className="account-page__identity is-guest" aria-label="还没登录">
            <span className="account-page__avatar" aria-hidden="true">
              <UserRound size={26} />
            </span>
            <div className="account-page__who">
              <h1>还没有登录</h1>
              <p>不登录也能用 —— 便条、皮肤、单词本都存在这台设备上。</p>
            </div>
          </section>

          <section className="account-page__note" aria-label="登录之后">
            <ShieldCheck size={16} />
            <p>
              登录（或注册一个新账号）之后，这些东西跟着账号走：换台设备、
              换个浏览器，便条和单词本都还在。注册只要名字、邮箱和密码，
              外加一枚验证码。
            </p>
          </section>

          <div className="account-page__actions">
            <button
              type="button"
              className="is-primary"
              onClick={() => setAuthOpen(true)}
            >
              <UserRound size={16} />
              登录 / 注册
            </button>
            <Link to="/shelf">
              <BookOpen size={16} />
              先回书架
            </Link>
          </div>
        </>
      )}

      {account.error ? (
        <p className="account-page__error" role="status">
          {account.error}
        </p>
      ) : null}

      {!user ? (
        <AuthDialog
          open={authOpen}
          onClose={closeAuth}
          initialView="signin"
        />
      ) : null}
    </main>
  );
}

export default AccountPage;
